func seedIssue2394StopIntents(t *testing.T, rt servedControlProofRuntime, runID, eventID string) {
	t.Helper()
	requireServedRunControlState(t, rt.DB, rt.Backend, runID, "paused", "paused")
	var prefixes []string
	for i := 0; i < 4; i++ {
		published := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": "item.processed", "run_id": runID, "source_event_id": eventID, "payload": map[string]any{"item_id": fmt.Sprintf("prefix-%d", i)}, "idempotency_key": uuid.NewString()})
		prefixes = append(prefixes, published.EventID)
	}
	var deliveryID string
	if err := rt.DB.QueryRow(`SELECT delivery_id FROM event_deliveries WHERE event_id=$1 AND subscriber_type='node' ORDER BY delivery_id LIMIT 1`, eventID).Scan(&deliveryID); err != nil {
		t.Fatal(err)
	}
	producer, err := events.NewRootRoutingSource(uuid.NewString())
	if err != nil {
		t.Fatal(err)
	}
	capsule := fanoutobligation.Capsule{NodeKey: "root.item-handler", ExecutionFlowID: "root", Route: runtimeflowidentity.StoredRoute("root", "root", "root"), HandlerEventKey: "item.received", ProducerSource: producer, Lineage: events.EventLineage{RunID: runID, ParentEventID: eventID, ExecutionMode: executionmode.Live}}
	collection := contracts.CatalogTypeReference{Type: "list<text>"}
	projection, err := contracts.AdmitCollectionProjection(collection)
	if err != nil {
		t.Fatal(err)
	}
	capsule.SourceProjection = contracts.FanOutPlanSemantics{ItemsFrom: "payload.items", CollectionType: collection, CollectionProjection: projection, ItemType: projection.ItemType(), ItemAlias: "entry", Identity: "entry", IdentityDerived: true, MaxItems: contracts.DefaultFanOutMaxItems, Emit: contracts.EmitSpec{Event: "item.processed"}}
	blocked, err := runtimefailures.MarshalEnvelope(runtimefailures.Normalize(runtimefailures.New(runtimefailures.ClassTargetUnreachable, "not_found", "runtime.fan_out", "serve", nil), "runtime.fan_out", "serve"))
	if err != nil {
		t.Fatal(err)
	}
	retry, err := runtimefailures.MarshalEnvelope(runtimefailures.Normalize(runtimefailures.New(runtimefailures.ClassDependencyUnavailable, "dependency_down", "runtime.fan_out", "serve", nil), "runtime.fan_out", "serve"))
	if err != nil {
		t.Fatal(err)
	}
	tx, err := rt.DB.BeginTx(context.Background(), nil)
	if err != nil {
		t.Fatal(err)
	}
	defer tx.Rollback()
	at := time.Now().UTC()
	for i := 0; i < 20; i++ {
		path := fmt.Sprintf("stop-fixture-%02d", i)
		element := contracts.FanOutElementRef{FlowPath: "root", Family: "fan_out", SemanticPath: path}
		capsule.SourceProjection.ElementRef = element
		digest, err := canonicaljson.Hash(capsule.SourceProjection)
		if err != nil {
			t.Fatal(err)
		}
		ref := contracts.FanOutPlanRef{BundleHash: rt.BundleHash, ElementRef: element, SemanticDigest: digest}
		if err := capsule.SourceProjection.Validate(ref); err != nil {
			t.Fatalf("admit exact cancellation fixture source: %v", err)
		}
		capsuleJSON, err := fanoutobligation.MarshalCapsule(capsule)
		if err != nil {
			t.Fatal(err)
		}
		status, cursor, generation := "open", 0, 0
		var claim, lease, reason, retryAt, retryFailure any
		switch i % 5 {
		case 1:
			cursor = 1
		case 2:
			claim, lease, generation = "held-fixture", at.Add(time.Hour), 7
		case 3:
			status, reason = "blocked", string(blocked)
		case 4:
			retryAt, retryFailure = at.Add(time.Hour), string(retry)
		}
		_, err = tx.Exec(`INSERT INTO fan_out_intents
		(run_id,triggering_delivery_id,flow_path,declaration_family,semantic_path,bundle_hash,semantic_digest,source_kind,source_event_id,source_field,cardinality,cursor,status,next_chunk_size,capsule,created_at,updated_at,claim_owner,claim_generation,lease_expires_at,blocked_reason,retry_ready_at,retry_failure)
		VALUES ($1,$2,'root','fan_out',$3,$4,$5,'event_payload_field',$6,'items',25,$7,$8,32,$9,$10,$10,$11,$12,$13,$14,$15,$16)`, runID, deliveryID, path, rt.BundleHash, digest, eventID, cursor, status, string(capsuleJSON), at, claim, generation, lease, reason, retryAt, retryFailure)
		if err != nil {
			t.Fatal(err)
		}
		if cursor == 1 {
			if _, err := tx.Exec(`INSERT INTO fan_out_outcomes (run_id,triggering_delivery_id,flow_path,declaration_family,semantic_path,ordinal,outcome_kind,event_id,created_at) VALUES ($1,$2,'root','fan_out',$3,0,'committed',$4,$5)`, runID, deliveryID, path, prefixes[i/5], at); err != nil {
				t.Fatal(err)
			}
		}
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}
}

