			write2376SourceFile(t, rootB, "README.md", "Serving source B, not the existing run's A.\n")
			opts.SourceRoot = rootB
			setServeRuntimeRecovery(t, opts.ConfigPath, false, true)
			b, servedB := start()
			defer b.stop()
