			}(); err != nil || published != 1 {
				t.Fatalf("signed raw event dedupe = %d, %v", published, err)
			}
			var serviceID string
			var journalCount int
			if err := reader.InspectSnapshot(context.Background(), func(ctx context.Context) error {
				var err error
				serviceID, err = storetest.ReadUnfilteredStandingServiceIDStorage(ctx, reader)
				return err
			}); err != nil {
				t.Fatal(err)
			}
			if err := reader.InspectSnapshot(context.Background(), func(ctx context.Context) error {
				var err error
				journalCount, err = storetest.CountStandingJournalStorage(ctx, reader)
				return err
			}); err != nil {
				t.Fatal(err)
			}
			secretsCLI([]string{"secrets", "set", "webhook_signing.telegram", "--stdin"}, "unadmitted-in-process-rotation\n")
			for _, command := range []string{"resume", "reset"} {
				response := requestServedJSONRPC(t, endpoint+"/v1/rpc", "standing."+command, map[string]any{"service_id": serviceID, "reason": "credential-currentness proof", "idempotency_key": "stale-standing-" + command})
