		name, value, presence string
		remove                bool
	}{{"rotation", "unadmitted-replacement", packs.RequirementStatusBound, false}, {"deletion", "", packs.RequirementStatusUnbound, true}, {"restoration_ABA", "original-secret", packs.RequirementStatusBound, false}, {"same_value_new_observation", "original-secret", packs.RequirementStatusBound, false}, {"unusable_value", " \t\n", packs.RequirementStatusUnbound, false}} {
