				}
			} else {
				set(mutation.value)
			}
			for j, secret := range []string{"original-secret", "unadmitted-replacement"} {
				want := http.StatusServiceUnavailable
				if policy == "unsigned" {
					want = http.StatusAccepted
				}
				if code := post(80100+i*10+j, secret); code != want {
